-- Phase 67: operational audits, inspections, evidence and corrective follow-up.
-- quality: allow-nonconcurrent-index reason=new-empty-phase67-tables
create schema if not exists operational_audit_private;
revoke all on schema operational_audit_private from public,anon,authenticated;

create table public.audit_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{audits:view}',scope_type text not null default 'store' check(scope_type in('organization','brand','region','cluster','store')),scope_ids uuid[] not null default '{}',assigned_only boolean not null default false,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.audit_template_library(id text primary key,name text not null,description text,audit_type text not null,definition jsonb not null,version integer not null default 1,read_only boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table public.audit_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,source_library_id text references public.audit_template_library(id) on delete set null,name text not null,description text,audit_type text not null,target_scope text not null check(target_scope in('organization','brand','region','cluster','store','department','asset','supplier')),status text not null default 'draft' check(status in('draft','published','archived')),current_version integer not null default 0,owner_user_id uuid references auth.users(id),scoring_method text not null default 'percentage' check(scoring_method in('percentage','weighted_percentage','pass_fail_only','no_score')),pass_threshold numeric(5,2),review_required boolean not null default false,not_applicable_policy jsonb not null default '{}',critical_policy jsonb not null default '{}',retention_policy jsonb not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,check(pass_threshold is null or pass_threshold between 0 and 100));
create table public.audit_template_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_id uuid not null references public.audit_templates(id) on delete restrict,version integer not null,status text not null default 'draft' check(status in('draft','published','retired')),definition_snapshot jsonb not null default '{}',scoring_method text not null,pass_threshold numeric(5,2),validation_result jsonb not null default '{}',calculation_hash text not null,created_by uuid references auth.users(id),published_by uuid references auth.users(id),created_at timestamptz not null default now(),published_at timestamptz,unique(template_id,version));
create table public.audit_template_sections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_version_id uuid not null references public.audit_template_versions(id) on delete cascade,title text not null,description text,order_index integer not null,weight numeric(10,4),required boolean not null default true,unique(template_version_id,order_index));
create table public.audit_template_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,section_id uuid not null references public.audit_template_sections(id) on delete cascade,item_key text not null,title text not null,description text,item_type text not null check(item_type in('yes_no','pass_fail','multiple_choice','numeric','text','photo_required','document_check','asset_check','temperature_or_measurement','signature_acknowledgement','custom_safe_type')),required boolean not null default true,weight numeric(10,4),critical boolean not null default false,evidence_requirement text not null default 'none' check(evidence_requirement in('none','optional','required_on_fail','always_required')),response_options jsonb not null default '[]',failure_action_policy jsonb not null default '{}',condition_definition jsonb,source_type text check(source_type is null or source_type in('documents','assets','maintenance','training','inventory','quality')),source_config jsonb not null default '{}',measurement_config jsonb not null default '{}',not_applicable_allowed boolean not null default false,order_index integer not null,unique(section_id,item_key),unique(section_id,order_index));
create table public.audit_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_id uuid not null references public.audit_templates(id) on delete restrict,scope_type text not null check(scope_type in('organization','brand','region','cluster','store','department','asset','supplier')),scope_id uuid,recurrence text check(recurrence is null or recurrence in('daily','weekly','monthly','quarterly','custom')),recurrence_config jsonb not null default '{}',missed_audit_policy text not null default 'mark_overdue' check(missed_audit_policy in('mark_overdue','create_next','skip','require_completion')),assigned_role_id uuid,assigned_user_id uuid references auth.users(id),active boolean not null default true,next_due_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create sequence if not exists public.audit_number_seq;
create sequence if not exists public.audit_finding_number_seq;
create table public.audits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,audit_number text not null,template_id uuid not null references public.audit_templates(id) on delete restrict,template_version_id uuid not null references public.audit_template_versions(id) on delete restrict,template_version integer not null,plan_id uuid references public.audit_plans(id) on delete set null,scope_type text not null,scope_id uuid,store_id uuid references public.establishments(id) on delete restrict,scheduled_for timestamptz,started_at timestamptz,completed_at timestamptz,auditor_user_id uuid not null references auth.users(id),reviewer_user_id uuid references auth.users(id),reviewed_at timestamptz,status text not null default 'scheduled' check(status in('scheduled','in_progress','pending_review','completed','cancelled','expired')),score numeric(7,2),result text not null default 'incomplete' check(result in('compliant','compliant_with_observations','non_compliant','critical_non_compliance','incomplete')),score_breakdown jsonb not null default '{}',published_at timestamptz,published_by uuid references auth.users(id),follow_up_of_audit_id uuid references public.audits(id) on delete set null,follow_up_type text check(follow_up_type is null or follow_up_type in('full_reaudit','findings_only','critical_items_only')),active_editor_user_id uuid references auth.users(id),editor_lock_expires_at timestamptz,version bigint not null default 1,offline_enabled boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,audit_number));
create table public.audit_responses(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid not null references public.audits(id) on delete cascade,template_item_id uuid not null references public.audit_template_items(id) on delete restrict,response_value jsonb not null default '{}',response_status text not null default 'unanswered' check(response_status in('pass','attention','fail','not_applicable','unanswered')),notes text,responded_by uuid references auth.users(id),responded_at timestamptz,score_component numeric(10,4),not_applicable_reason text,source_snapshot jsonb,source_observed_at timestamptz,version bigint not null default 1,client_mutation_id uuid,updated_at timestamptz not null default now(),unique(audit_id,template_item_id));
create table public.audit_evidence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid not null references public.audits(id) on delete cascade,response_id uuid references public.audit_responses(id) on delete set null,evidence_type text not null check(evidence_type in('photo','file','note','document_reference','asset_reference','measurement','incident_reference','work_order_reference')),file_id uuid references public.internal_attachments(id) on delete restrict,reference_type text,reference_id uuid,captured_at timestamptz not null,captured_by uuid not null references auth.users(id),metadata jsonb not null default '{}',visibility text not null default 'audit_team' check(visibility in('audit_team','management','restricted')),revoked_at timestamptz,revoked_by uuid references auth.users(id),revoke_reason text,created_at timestamptz not null default now(),check(file_id is not null or reference_id is not null or evidence_type in('note','measurement')));
create table public.audit_findings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,finding_number text not null,audit_id uuid not null references public.audits(id) on delete cascade,response_id uuid references public.audit_responses(id) on delete set null,template_item_id uuid references public.audit_template_items(id) on delete set null,finding_type text not null check(finding_type in('observation','minor_nonconformity','major_nonconformity','critical_nonconformity','improvement_opportunity')),severity text not null check(severity in('low','medium','high','critical')),title text not null,description text not null,source text not null check(source in('manual','rule','linked_module','ai_draft')),status text not null default 'open' check(status in('open','action_in_progress','awaiting_verification','verified','accepted_risk','closed')),owner_user_id uuid references auth.users(id),due_at timestamptz,related_nonconformity_id uuid references public.quality_nonconformities(id) on delete restrict,related_work_order_id uuid references public.maintenance_work_orders(id) on delete restrict,related_incident_id uuid references public.operational_incidents(id) on delete restrict,training_recommendation jsonb,accepted_risk_approval_id uuid references public.internal_approvals(id),accepted_risk_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,finding_number));
create table public.audit_action_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid not null references public.audits(id) on delete cascade,finding_id uuid references public.audit_findings(id) on delete set null,title text not null,owner_user_id uuid references auth.users(id),status text not null default 'open' check(status in('open','in_progress','awaiting_verification','completed','cancelled')),target_completion_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_action_plan_tasks(action_plan_id uuid not null references public.audit_action_plans(id) on delete cascade,internal_task_id uuid not null references public.internal_tasks(id) on delete restrict,created_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(action_plan_id,internal_task_id));
create table public.audit_finding_verifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,finding_id uuid not null references public.audit_findings(id) on delete cascade,verifier_user_id uuid not null references auth.users(id),decision text not null check(decision in('verified','rejected','needs_more_evidence')),notes text,evidence_ids uuid[] not null default '{}',segregation_checked boolean not null default false,created_at timestamptz not null default now());
create table public.audit_amendments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid not null references public.audits(id) on delete restrict,reason text not null,corrected_fields jsonb not null,original_result jsonb not null,amendment_version integer not null,changed_by uuid not null references auth.users(id),changed_at timestamptz not null default now(),unique(audit_id,amendment_version));
create table public.audit_sync_events(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid not null references public.audits(id) on delete cascade,response_id uuid references public.audit_responses(id) on delete set null,offline_mutation_id uuid references public.offline_server_mutations(id) on delete set null,device_id uuid references public.offline_devices(id) on delete set null,template_version_id uuid not null references public.audit_template_versions(id),expected_version bigint,idempotency_key text not null,status text not null default 'pending' check(status in('pending','applied','duplicate','conflict','rejected','retrying')),conflict_summary jsonb,last_error text,client_created_at timestamptz not null,server_received_at timestamptz not null default now(),applied_at timestamptz,unique(organization_id,idempotency_key));
create table public.audit_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid references public.audit_plans(id) on delete cascade,audit_id uuid references public.audits(id) on delete cascade,job_type text not null check(job_type in('schedule_instance','mark_overdue','sync_evidence','refresh_source','analytics_snapshot','follow_up_reminder')),status text not null default 'pending' check(status in('pending','processing','retrying','completed','failed','dead_letter')),payload jsonb not null default '{}',idempotency_key text not null,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),locked_at timestamptz,locked_by text,result jsonb,error_message text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.audit_store_opening_links(audit_id uuid not null references public.audits(id) on delete cascade,opening_project_id uuid not null references public.store_opening_projects(id) on delete cascade,opening_blocker_id uuid references public.store_opening_blockers(id) on delete set null,link_type text not null default 'readiness_check' check(link_type in('readiness_check','go_live_gate','follow_up','blocker_evidence')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(audit_id,opening_project_id,link_type));
create table public.operational_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,audit_id uuid references public.audits(id) on delete set null,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create table public.fact_audits(audit_id uuid primary key,organization_id uuid not null,store_id uuid,template_id uuid,template_version integer,status text,result text,score numeric,scheduled_for timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_audit_responses(response_id uuid primary key,organization_id uuid not null,audit_id uuid not null,template_item_id uuid not null,response_status text,score_component numeric,responded_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_audit_findings(finding_id uuid primary key,organization_id uuid not null,audit_id uuid not null,finding_type text,severity text,status text,created_at timestamptz,closed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_audit_action_plans(action_plan_id uuid primary key,organization_id uuid not null,audit_id uuid not null,finding_id uuid,status text,target_completion_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_audit_followups(audit_id uuid primary key,organization_id uuid not null,follow_up_of_audit_id uuid not null,follow_up_type text,status text,scheduled_for timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.dim_audit_template(template_id uuid primary key,organization_id uuid not null,name text,audit_type text,status text,current_version integer,loaded_at timestamptz not null default now());
create table public.dim_audit_type(audit_type text primary key,label text not null);
create table public.dim_finding_type(finding_type text primary key,label text not null);
create table public.dim_finding_severity(severity text primary key,label text not null,rank integer not null);
create table public.dim_audit_result(result text primary key,label text not null);

