create index audit_templates_scope_idx on public.audit_templates(organization_id,status,audit_type,updated_at desc);
create index audit_plans_due_idx on public.audit_plans(organization_id,active,next_due_at)where active;
create index audits_board_idx on public.audits(organization_id,status,scheduled_for,created_at desc);
create index audits_store_idx on public.audits(organization_id,store_id,status,scheduled_for);
create index audit_responses_audit_idx on public.audit_responses(audit_id,response_status,updated_at);
create index audit_findings_scope_idx on public.audit_findings(organization_id,status,severity,due_at);
create index audit_jobs_claim_idx on public.audit_jobs(status,available_at,created_at)where status in('pending','retrying');
create index operational_audit_events_idx on public.operational_audit_events(organization_id,audit_id,created_at desc);

create or replace function operational_audit_private.can_access(target_org uuid,target_audit uuid default null,requested_permission text default 'audits:view')returns boolean language sql stable security definer set search_path='' as $$select(select auth.uid())is not null and(exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=(select auth.uid())and om.active and om.role in('owner','admin'))or exists(select 1 from public.audit_member_permissions p where p.organization_id=target_org and p.user_id=(select auth.uid())and p.active and(requested_permission=any(p.permissions)or'audits:view_network'=any(p.permissions))and(not p.assigned_only or target_audit is null or exists(select 1 from public.audits a where a.id=target_audit and(a.auditor_user_id=(select auth.uid())or a.reviewer_user_id=(select auth.uid())))))or exists(select 1 from public.audits a join public.establishment_members em on em.establishment_id=a.store_id where a.id=target_audit and a.organization_id=target_org and em.user_id=(select auth.uid())and em.status='active'and requested_permission='audits:view'));$$;
revoke all on function operational_audit_private.can_access(uuid,uuid,text)from public,anon;grant execute on function operational_audit_private.can_access(uuid,uuid,text)to authenticated;
do $$declare t text;begin foreach t in array array['audit_member_permissions','audit_template_library','audit_templates','audit_template_versions','audit_template_sections','audit_template_items','audit_plans','audits','audit_responses','audit_evidence','audit_findings','audit_action_plans','audit_action_plan_tasks','audit_finding_verifications','audit_amendments','audit_sync_events','audit_store_opening_links','audit_jobs','operational_audit_events','fact_audits','fact_audit_responses','fact_audit_findings','fact_audit_action_plans','fact_audit_followups','dim_audit_template','dim_audit_type','dim_finding_type','dim_finding_severity','dim_audit_result']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','audit_service_'||t,t);end loop;end$$;

create or replace function public.claim_audit_jobs(requested_worker text,requested_limit integer default 10)returns setof public.audit_jobs language plpgsql security definer set search_path='' as $$begin return query update public.audit_jobs j set status='processing',locked_at=now(),locked_by=requested_worker,attempts=j.attempts+1 where j.id in(select id from public.audit_jobs where status in('pending','retrying')and available_at<=now()order by created_at limit least(greatest(requested_limit,1),50)for update skip locked)returning j.*;end$$;
revoke all on function public.claim_audit_jobs(text,integer)from public,anon,authenticated;grant execute on function public.claim_audit_jobs(text,integer)to service_role;
create or replace function public.publish_operational_audit(requested_audit_id uuid,requested_actor uuid)returns public.audits language plpgsql security definer set search_path='' as $$declare a public.audits;t public.audit_templates;r public.audits;begin select * into a from public.audits where id=requested_audit_id for update;if not found then raise exception 'audit not found';end if;if a.status not in('pending_review','completed')then raise exception 'audit is not complete';end if;select * into t from public.audit_templates where id=a.template_id;if t.review_required and a.reviewed_at is null then raise exception 'review required';end if;if a.result='incomplete'then raise exception 'incomplete audit cannot be published';end if;if exists(select 1 from public.audit_template_items i join public.audit_template_sections s on s.id=i.section_id left join public.audit_responses ar on ar.audit_id=a.id and ar.template_item_id=i.id where s.template_version_id=a.template_version_id and i.required and(coalesce(ar.response_status,'unanswered')='unanswered'))then raise exception 'required responses missing';end if;update public.audits set status='completed',published_at=now(),published_by=requested_actor,active_editor_user_id=null,editor_lock_expires_at=null,version=version+1,updated_at=now()where id=a.id returning * into r;return r;end$$;
revoke all on function public.publish_operational_audit(uuid,uuid)from public,anon,authenticated;grant execute on function public.publish_operational_audit(uuid,uuid)to service_role;

alter table public.store_feature_flags add column if not exists operational_audits_enabled boolean not null default false,add column if not exists audit_offline_enabled boolean not null default false,add column if not exists audit_scoring_enabled boolean not null default false,add column if not exists audit_followups_enabled boolean not null default false,add column if not exists audit_ai_assistant_enabled boolean not null default false;
alter table public.plans add column if not exists operational_audits_enabled boolean not null default false,add column if not exists audit_offline_enabled boolean not null default false,add column if not exists audit_scoring_enabled boolean not null default false,add column if not exists audit_followups_enabled boolean not null default false,add column if not exists audit_ai_assistant_enabled boolean not null default false;

